import {createHash} from 'node:crypto';
import {readFile,readdir,writeFile} from 'node:fs/promises';

const directory=new URL('../supabase/migrations/',import.meta.url);
const names=(await readdir(directory)).filter(name=>name.endsWith('.sql')).sort();
const parts=[
  '-- GENERATED by: node scripts/prepare-bootstrap.mjs',
  '-- Rebuild the application schema in a NEW, EMPTY Supabase project only.',
  '-- Contains no live accounts, messages, passwords or private keys.',
  '-- Run supabase/schedule.sql separately after a successful bootstrap.',
  '-- This script does not reconcile Supabase CLI migration history.',
  'begin;',
  `do $bootstrap$ begin
  if to_regclass('public.members') is not null or to_regclass('public.intentions') is not null
     or to_regclass('public.community_totals') is not null then
    raise exception 'Bootstrap is only for a new, empty project. Existing data must not be overwritten.';
  end if;
end $bootstrap$;`,
];
for(const name of names){
  const sql=await readFile(new URL(name,directory),'utf8');
  const digest=createHash('sha256').update(sql).digest('hex');
  parts.push(`-- SOURCE: ${name}\n-- SHA256: ${digest}\n${sql.trim()}`);
}
parts.push('commit;','');
await writeFile(new URL('../supabase/bootstrap.sql',import.meta.url),parts.join('\n\n').trimEnd()+'\n');
console.log(`Prepared supabase/bootstrap.sql from ${names.length} migrations.`);
